// Batch prober: reads JSON array of input strings from argv[2] (file), runs executable, writes JSON array of {in,out,rc} to stdout
import { execFile } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test4_executable';
const inputs = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const CONC = Number(process.argv[3] || 24);
const results = new Array(inputs.length);
let idx = 0;
function next(done) {
  if (idx >= inputs.length) return done();
  const i = idx++;
  execFile(EXE, ['--a', inputs[i]], { maxBuffer: 1 << 26, encoding: 'utf8' }, (err, so, se) => {
    results[i] = { i, out: so, err: se, rc: err ? (err.code ?? 1) : 0 };
    next(done);
  });
}
let live = CONC, fin = 0;
const finish = () => { if (++fin === live) process.stdout.write(JSON.stringify(results)); };
for (let k = 0; k < CONC; k++) next(finish);

