import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
const meta = JSON.parse(readFileSync('/tmp/probe/mine/meta1.json','utf8'));
const lines = readFileSync('/tmp/probe/mine/out1.txt','utf8').split('\n');
const rows = lines.map(l => { const p = l.split('  ->  '); return {in: JSON.parse(p[0]), out: p[1].startsWith('"')?JSON.parse(p[1]):p[1]}; });
const CTXN = [...new Set(meta.map(m=>m[1]))];
const KW = [...new Set(meta.map(m=>m[0]))];
const map = new Map();
rows.forEach((r,i)=>{ map.set(meta[i][0]+'|'+meta[i][1], r); });
// cell classification
function cls(kw, r) {
  const o = r.out;
  if (o.includes(kw.toUpperCase())) return 'U';
  if (o.toLowerCase().includes(kw)) return '.';
  return '?';
}
let hdr = 'KW'.padEnd(11) + CTXN.map(c=>c.slice(0,4).padEnd(5)).join('');
let out = [hdr];
for (const k of KW) {
  let line = k.padEnd(11);
  for (const c of CTXN) { const r = map.get(k+'|'+c); line += cls(k,r).padEnd(5); }
  out.push(line);
}
out.push('');
out.push('CTX legend: ' + CTXN.map((c,i)=>c.slice(0,4)+'='+c).join('  '));
writeFileSync('/tmp/probe/mine/tbl1.txt', out.join('\n'));
console.log(out.join('\n'));
EOF
